# Source: Hasan, M. R. & Khan, B. (2023), PLOS ONE Table 4
# https://doi.org/10.1371/journal.pone.0288844
# Source counts: treatment passed 29 / 32; control passed 24 / 33.
# Outputs underlying CSV and checks calculations; visual generated by upgrade_baiqa.py.
from pathlib import Path
import csv
rows=list(csv.DictReader((Path(__file__).parent/'hasan_khan_2023_trial_pass_rates.csv').open()))
for r in rows:
    p=int(r['passed'])/int(r['total'])*100
    print(f"{r['group']}: {p:.4f}% passed ({r['passed']}/{r['total']})")
print('Percentage-point difference:',round(100*(29/32-24/33),4))
